      "path": "packages/plugin/src/client-secure-transport.ts",
      "content": "import { SerialSend } from '@dsh-remote/webrtc'\nimport { NoiseIkSession, createNoisePrologue } from '@dsh-remote/crypto'\nimport { SecureMessageCodec, MAX_SECURE_MESSAGE_BYTES } from '@dsh-remote/protocol'\nimport type { RemoteTransport, SecureHandshakeTransport } from '@dsh-remote/webrtc'\nimport type { HostIdentity, TrustedPeer } from './identity-store.js'\n\n/** Client-side Noise IK wrapper used by the local Harness remote-mode runtime. */\nexport class ClientSecureTransport implements RemoteTransport {\n  private noise?: NoiseIkSession\n  private unsubscribeInner?: () => void\n  private readonly incoming = new SecureMessageCodec()\n  private readonly outgoing = new SecureMessageCodec()\n  private closed = false\n  private lifetime?: AbortController\n  private readonly sends = new SerialSend()\n  private closeError?: Error\n\n  constructor(\n    private readonly inner: SecureHandshakeTransport,\n    private readonly identity: HostIdentity,\n    private readonly host: TrustedPeer,\n  ) {}\n\n  async connect(): Promise<void> {\n    const lifetime = new AbortController()\n    this.lifetime = lifetime\n    this.closed = false\n    this.closeError = undefined\n    this.incoming.reset()\n    this.outgoing.reset()\n    await this.inner.connect()\n    lifetime.signal.throwIfAborted()\n    const info = this.inner.connectionInfo()\n    if (info.localDeviceId !== this.identity.deviceId || info.remoteDeviceId !== this.host.deviceId) {\n      await this.inner.close()\n      throw Object.assign(new Error('The relay connection is bound to an unexpected device.'), { code: 'PEER_IDENTITY_MISMATCH' })\n    }\n    const noise = new NoiseIkSession({\n      role: 'initiator',\n      localPrivateKey: this.identity.privateKey,\n      localPublicKey: this.identity.publicKey,\n      remotePublicKey: this.host.publicKey,\n      prologue: createNoisePrologue(info.connectionId, this.host.deviceId, this.identity.deviceId),\n    })\n    this.noise = noise\n    try {\n      await waitForResponder(this.inner, noise, lifetime.signal)\n      this.inner.markSecureReady?.()\n    } catch (error) {\n      noise.destroy()\n      if (this.lifetime === lifetime) {\n        this.noise = undefined\n        await this.inner.close()\n      }\n      throw error\n    }\n  }\n\n  async send(data: Uint8Array): Promise<void> {\n    if (data.byteLength > MAX_SECURE_MESSAGE_BYTES) throw new Error('Secure message exceeds the reassembly limit.')\n    const noise = this.requireNoise()\n    try {\n      await this.sends.run(data.byteLength, async () => {\n        if (this.closed || this.noise !== noise) throw new Error('Secure transport replaced')\n        for (const plaintext of this.outgoing.encode(data)) await this.inner.send(noise.encrypt(plaintext))\n      })\n    } catch (error) {\n      await this.close().catch(() => undefined)\n      throw error\n    }\n  }\n\n  onMessage(handler: (data: Uint8Array) => void): () => void {\n    this.unsubscribeInner?.()\n    this.unsubscribeInner = this.inner.onMessage(data => {\n      const noise = this.noise\n      if (noise === undefined || !noise.complete || this.closed) return\n      try {\n        const message = this.incoming.decode(noise.decrypt(data))\n        if (message !== undefined) handler(message)\n      } catch {\n        this.closeError = Object.assign(new Error('The authenticated Remote channel rejected a frame.'), { code: 'SECURE_CHANNEL_FAILED' })\n        void this.close()\n      }\n    })\n    return () => {\n      this.unsubscribeInner?.()\n      this.unsubscribeInner = undefined\n    }\n  }\n\n  onClose(handler: (error?: Error) => void): () => void {\n    return this.inner.onClose?.(error => handler(this.closeError ?? error)) ?? (() => undefined)\n  }\n\n  async close(): Promise<void> {\n    if (this.closed) return\n    this.closed = true\n    this.lifetime?.abort()\n    this.lifetime = undefined\n    this.unsubscribeInner?.()\n    this.unsubscribeInner = undefined\n    this.incoming.reset()\n    this.outgoing.reset()\n    this.noise?.destroy()\n    this.noise = undefined\n    await this.inner.close()\n  }\n\n  getStats() { return this.inner.getStats() }\n\n  private requireNoise(): NoiseIkSession {\n    if (this.noise === undefined || !this.noise.complete || this.closed) {\n      throw new Error('The authenticated Noise channel is not connected.')\n    }\n    return this.noise\n  }\n}\n\nasync function waitForResponder(inner: SecureHandshakeTransport, noise: NoiseIkSession, signal: AbortSignal): Promise<void> {\n  await new Promise<void>((resolve, reject) => {\n    let settled = false\n    let unsubscribe = () => {}\n    let unsubscribeClose = () => {}\n    const timer = setTimeout(() => finish(new Error('Noise IK handshake timed out.')), 10_000)\n    const onAbort = () => finish(new Error('Noise IK handshake was aborted.'))\n    const finish = (error?: Error): void => {\n      if (settled) return\n      settled = true\n      clearTimeout(timer)\n      unsubscribe()\n      unsubscribeClose()\n      signal.removeEventListener('abort', onAbort)\n      if (error === undefined) resolve()\n      else reject(error)\n    }\n    unsubscribe = inner.onHandshake((step, data) => {\n      if (settled) return\n      try {\n        if (step !== 2) throw new Error('Noise IK responder sent an out-of-order handshake message.')\n        noise.readHandshake(data)\n        if (!noise.complete) throw new Error('Noise IK handshake did not complete.')\n        finish()\n      } catch (error) {\n        finish(Object.assign(error instanceof Error ? error : new Error('Noise IK handshake failed.'), { code: 'SECURE_CHANNEL_FAILED' }))\n      }\n    })\n    unsubscribeClose = inner.onClose?.(error => finish(error ?? new Error('Control channel closed during Noise IK handshake.'))) ?? (() => {})\n    signal.addEventListener('abort', onAbort, { once: true })\n    if (signal.aborted) { onAbort(); return }\n    void inner.sendHandshake(1, noise.writeHandshake()).catch(error => {\n      finish(error instanceof Error ? error : new Error('Noise IK handshake failed.'))\n    })\n  })\n}\n"
    },
    {
      "path": "packages/plugin/src/connection-controller.ts",
      "content": "import {\n  MAX_SECURE_MESSAGE_BYTES,\n  createRpcError,\n  encodeMessage,\n  type RemoteMessage,\n} from '@dsh-remote/protocol'\nimport type { IdentityStore } from './identity-store.js'\nimport type { SafeLogger } from './logging.js'\nimport type { RpcRouter } from './rpc-router.js'\nimport type { AuthenticatedPeerChannel } from './types.js'\n\ninterface ActiveConnection {\n  channel: AuthenticatedPeerChannel\n  router: RpcRouter\n  unsubscribe: () => void\n}\n\nexport interface PeerConnectionContext {\n  peerIdentityKey?: string\n  transportMode?: () => AuthenticatedPeerChannel['mode']\n  connectionId: string\n  peerDeviceId: string\n}\n\nexport interface ConnectedPeer {\n  deviceId: string\n  mode?: 'LAN' | 'P2P' | 'TURN' | 'Relay'\n}\n\n/**\n * Who closed the logical peer connection. `CONNECTION_FAILED` exists as both\n * a Server-issued code and a Host fallback, so the disconnect log must name the\n * source or operators cannot tell the two paths apart.\n */\nexport interface ConnectionCloseDetail {\n  closedBy: 'server' | 'host'\n  retryable?: boolean\n}\n\nexport type RpcRouterFactory = (\n  context: PeerConnectionContext,\n  send: (message: RemoteMessage) => Promise<void>,\n) => RpcRouter\n\nexport class ConnectionController {\n  private readonly active = new Map<string, ActiveConnection>()\n  private acceptQueue: Promise<void> = Promise.resolve()\n\n  constructor(\n    private readonly identities: IdentityStore,\n    private readonly createRouter: RpcRouterFactory,\n    private readonly logger?: SafeLogger,\n  ) {}\n\n  accept(channel: AuthenticatedPeerChannel): Promise<void> {\n    const operation = this.acceptQueue.then(() => this.acceptOne(channel))\n    this.acceptQueue = operation.catch(() => undefined)\n    return operation\n  }\n\n  private async acceptOne(channel: AuthenticatedPeerChannel): Promise<void> {\n    if (channel.security?.protocol !== 'Noise_IK_25519_ChaChaPoly_SHA256'\n      || channel.security.connectionId === ''\n      || channel.security.membershipId === '') {\n      await channel.close('SECURE_CHANNEL_FAILED')\n      throw new ConnectionRejectedError('SECURE_CHANNEL_FAILED', 'The channel is missing its authenticated Noise or membership context.')\n    }\n    if (!this.identities.isTrusted(channel.peerDeviceId, channel.peerIdentityKey)) {\n      await channel.close('PEER_IDENTITY_MISMATCH')\n      throw new ConnectionRejectedError('PEER_IDENTITY_MISMATCH', 'The peer identity does not match local trust.')\n    }\n    const connectionId = channel.security.connectionId\n    const connectionConflict = this.active.get(connectionId)\n    if (connectionConflict !== undefined && connectionConflict.channel.peerDeviceId !== channel.peerDeviceId) {\n      await channel.close('SECURE_CHANNEL_FAILED')\n      throw new ConnectionRejectedError('SECURE_CHANNEL_FAILED', 'The connection id is already bound to another peer.')\n    }\n\n    const replaced = [...this.active.values()].filter(connection => (\n      connection.channel.peerDeviceId === channel.peerDeviceId\n      || connection.channel.security.connectionId === connectionId\n    ))\n    if (replaced.length > 0) {\n      this.logger?.warn('replacing active peer connection', {\n        peerDeviceId: shortId(channel.peerDeviceId),\n        replacedCount: replaced.length,\n        replacedPeerDeviceIds: replaced.map(connection => shortId(connection.channel.peerDeviceId)),\n      })\n    }\n    await Promise.all(replaced.map(connection => this.disconnect(connection, 'CONNECTION_REPLACED')))\n\n    const router = this.createRouter(\n      { connectionId, peerDeviceId: channel.peerDeviceId, peerIdentityKey: channel.peerIdentityKey, transportMode: () => channel.mode },\n      message => this.sendTo(connectionId, channel, message),\n    )\n    const connection: ActiveConnection = {\n      channel,\n      router,\n      unsubscribe: () => undefined,\n    }\n    this.active.set(connectionId, connection)\n    try {\n      connection.unsubscribe = channel.onMessage(message => { void this.handle(connection, message) })\n    } catch (error) {\n      await this.disconnect(connection)\n      throw error\n    }\n    this.logger?.info('peer connection accepted', {\n      peerDeviceId: shortId(channel.peerDeviceId),\n      connectionId: shortId(connectionId),\n      mode: channel.mode,\n    })\n  }\n\n  isOnline(): boolean { return this.active.size > 0 }\n\n  connectionCount(): number { return this.active.size }\n\n  peerDeviceIds(): string[] {\n    return this.connectedPeers().map(peer => peer.deviceId)\n  }\n\n  connectedPeers(): ConnectedPeer[] {\n    const peers: ConnectedPeer[] = []\n    const seen = new Set<string>()\n    for (const connection of this.active.values()) {\n      const deviceId = connection.channel.peerDeviceId\n      if (seen.has(deviceId)) continue\n      seen.add(deviceId)\n      peers.push({\n        deviceId,\n        ...(connection.channel.mode === undefined ? {} : { mode: connection.channel.mode }),\n      })\n    }\n    return peers\n  }\n\n  peerDeviceId(): string | undefined {\n    const peers = this.peerDeviceIds()\n    return peers.length === 1 ? peers[0] : undefined\n  }\n\n  connectionMode(): 'LAN' | 'P2P' | 'TURN' | 'Relay' | 'Disconnected' {\n    const connection = this.active.values().next().value as ActiveConnection | undefined\n    return connection?.channel.mode ?? (connection === undefined ? 'Disconnected' : 'Relay')\n  }\n\n  async send(message: RemoteMessage): Promise<void> {\n    await Promise.all([...this.active.values()].map(connection => this.sendConnection(connection, message)))\n  }\n\n  async revoke(deviceId: string): Promise<void> {\n    const revoked = [...this.active.values()].filter(connection => connection.channel.peerDeviceId === deviceId)\n    await Promise.all(revoked.map(connection => this.disconnect(connection, 'DEVICE_REVOKED')))\n  }\n\n  async closeConnection(connectionId: string, code?: string, detail?: ConnectionCloseDetail): Promise<boolean> {\n    const connection = this.active.get(connectionId)\n    if (connection === undefined) return false\n    await this.disconnect(connection, code, detail)\n    return true\n  }\n\n  async close(): Promise<void> {\n    await this.acceptQueue\n    await Promise.all([...this.active.values()].map(connection => this.disconnect(connection)))\n  }\n\n  private async handle(connection: ActiveConnection, message: RemoteMessage): Promise<void> {\n    if (!this.isActive(connection)) return\n    try {\n      const response = await connection.router.handle(message)\n      if (!this.isActive(connection)) return\n      const responseBytes = encodeMessage(response).byteLength\n      let outbound: RemoteMessage\n      if (responseBytes <= MAX_SECURE_MESSAGE_BYTES) {\n        outbound = response\n      } else {\n        const endpoint = extractEndpoint(message)\n        this.logger?.warn('host response exceeds secure channel', {\n          endpoint,\n          bytes: responseBytes,\n          limit: MAX_SECURE_MESSAGE_BYTES,\n        })\n        outbound = createRpcError(\n          message.id,\n          'RESPONSE_TOO_LARGE',\n          'The Host response is too large for the secure Remote channel. Request a smaller page.',\n          { maxBytes: MAX_SECURE_MESSAGE_BYTES },\n          true,\n        )\n      }\n      await connection.channel.send(outbound)\n    } catch (error) {\n      this.logger?.warn('peer message handling failed; disconnecting', {\n        peerDeviceId: shortId(connection.channel.peerDeviceId),\n        reason: diagnosticReason(error),\n      })\n      await this.disconnect(connection)\n    }\n  }\n\n  private async sendTo(connectionId: string, channel: AuthenticatedPeerChannel, message: RemoteMessage): Promise<void> {\n    const connection = this.active.get(connectionId)\n    if (connection === undefined || connection.channel !== channel) {\n      throw new Error('peer channel is not active')\n    }\n    await this.sendConnection(connection, message)\n  }\n\n  private async sendConnection(connection: ActiveConnection, message: RemoteMessage): Promise<void> {\n    if (!this.isActive(connection)) {\n      throw new Error('peer channel is not active')\n    }\n    try {\n      await connection.channel.send(message)\n    } catch (error) {\n      this.logger?.warn('peer send failed; disconnecting', {\n        peerDeviceId: shortId(connection.channel.peerDeviceId),\n        messageType: message.type,\n        reason: diagnosticReason(error),\n      })\n      await this.disconnect(connection)\n      throw error instanceof Error ? error : new Error('peer send failed', { cause: error })\n    }\n  }\n\n  private async disconnect(\n    connection: ActiveConnection,\n    code?: string,\n    detail?: ConnectionCloseDetail,\n  ): Promise<void> {\n    if (!this.isActive(connection)) return\n    this.active.delete(connection.channel.security.connectionId)\n    connection.unsubscribe()\n    try {\n      await connection.router.closePeerStreams()\n    } finally {\n      await connection.channel.close(code)\n    }\n    this.logger?.info('peer connection disconnected', {\n      peerDeviceId: shortId(connection.channel.peerDeviceId),\n      connectionId: shortId(connection.channel.security.connectionId),\n      code: code ?? 'closed',\n      closedBy: detail?.closedBy ?? 'host',\n      ...(detail?.retryable === undefined ? {} : { retryable: detail.retryable }),\n    })\n  }\n\n  private isActive(connection: ActiveConnection): boolean {\n    return this.active.get(connection.channel.security.connectionId) === connection\n  }\n}\n\nexport class ConnectionRejectedError extends Error {\n  constructor(readonly code: string, message: string) { super(message) }\n}\n\nfunction diagnosticReason(error: unknown): string {\n  const message = error instanceof Error ? error.message : String(error)\n  return message.replace(/\\s+/g, ' ').slice(0, 160) || 'Unknown peer connection failure.'\n}\n\nfunction extractEndpoint(message: RemoteMessage): string | undefined {\n  if (!isRecord(message) || !isRecord(message.payload)) return undefined\n  const payload = message.payload\n  if (isRecord(payload.params)) {\n    if (typeof payload.params.endpoint === 'string') return payload.params.endpoint\n    if (typeof payload.params.method === 'string') return payload.params.method\n  }\n  if (typeof payload.endpoint === 'string') return payload.endpoint\n  if (typeof payload.method === 'string') return payload.method\n  return undefined\n}\n\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n  return typeof value === 'object' && value !== null && !Array.isArray(value)\n}\n\nfunction shortId(value: string): string { return value.length <= 12 ? value : `${value.slice(0, 8)}…${value.slice(-4)}` }\n"
